parameters.jsCode:
const canonical = $('When Executed by Another Workflow').first().json;

const riskPolicy =
  $('Parse Mandatory Risk Policy').first().json.risk_policy;
const request = {
  title: canonical.title,
  description: canonical.description,
  department: canonical.department,
  submitted_by: canonical.submitted_by || '',
  submitted_at: canonical.submitted_at || ''
};

const results = $input.all().map(item => item.json);

const retrievedKnowledge = results.map(result => {
  const metadata = result.document?.metadata || {};

const documentTitle = metadata.title || 'Unknown document';
const sectionTitle = metadata.section_title || 'Unknown section';

return {
  source_label: `${documentTitle} — ${sectionTitle}`,
  document_title: documentTitle,
  section_title: sectionTitle,
  content: result.document?.pageContent || '',
  score: result.score,
  metadata: {
    document_id: metadata.document_id,
    department: metadata.department,
    document_type: metadata.document_type,
    version: metadata.version,
    effective_date: metadata.effective_date,
    owner: metadata.owner,
    status: metadata.status
  }
};
});

const jiraLabelPolicy = {
  department: [
    "customer-support",
    "sales",
    "finance",
    "hr",
    "it-operations"
  ],
  work_type: [
    "ai-automation",
    "process-improvement",
    "knowledge-management"
  ],
  stage: [
    "discovery",
    "pilot",
    "production"
  ]
};


return [
  {
    json: {
      request,
      retrieved_knowledge: retrievedKnowledge,
      jira_label_policy: jiraLabelPolicy,
      mandatory_risk_policy: riskPolicy,
    }
  }
];

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const fileText = buffer.toString('utf8');

// Remove YAML front matter
const content = fileText
  .replace(/^---\s*\n[\s\S]*?\n---\s*\n/, '')
  .trim();

return [
  {
    json: {
      risk_policy: content
    }
  }
];

