const assessment = $('RAG Recommendation').first().json.output;
const ragContext = $('Prepare RAG Context').first().json;

const retrievedSources = [
  ...new Set(
    (ragContext.retrieved_knowledge || [])
      .map(item => item.document_title)
      .filter(Boolean)
  )
];

return [
  {
    json: {
      output: assessment,
      retrieved_sources: retrievedSources
    }
  }
];
